#define int long long
const int N=55;
int n,m,depth[N],f[N],b[N],id[N][N];
pair<int,int>a[N];
vector<int>g[N];
int lca(int u,int v){
    while(u!=v){
        if(depth[u]<depth[v]){
            v=f[v];
        }
        else{
            u=f[u];
        }
    }
    return u;
}
void dfs(int u,int last){
    depth[u]=depth[last]+1,f[u]=last;
    for(int v:g[u]){
        if(v!=last){
            dfs(v,u);
        }
    }
}
void color(int u,int v){
    if(lca(u,v)!=u&&lca(u,v)!=v){
        color(u,lca(u,v)),color(v,lca(u,v));
        return;
    }
    if(depth[v]>depth[u]){
        swap(u,v);
    }
    if(u==v){
        return;
    }
    while(u!=v){
        b[id[u][f[u]]]=1;
        u=f[u];
    }
}
int calc(int S){//这个集合是坏掉的 也就是都不亮
    memset(b,0,sizeof(b));
    for(int i=0;i<m;i++){
        if(S>>i&1){
            color(a[i].first,a[i].second);
        }
    }
    int sum=0;
    for(int i=1;i<n;i++){
        sum+=!b[i];
    }
    return (1ll<<sum);
}
